<?php require_once __DIR__.'/../auth.php'; require_login(); page_start('Practical 13 — Fetch API Event CRUD'); ?>
<p>Events load from a JSON endpoint without reloading the page. Viewing requires login; add/edit/delete require the admin role.</p><p id="message" class="flash" hidden></p>
<?php if(($_SESSION['role']??'')==='admin'):?><form id="eventForm"><input type="hidden" id="eventId"><label>Title</label><input id="title" required><label>Category</label><select id="category"><option>Technology</option><option>Sports</option><option>Cultural</option><option>Career</option><option>Workshop</option><option>Other</option></select><label>Date</label><input id="eventDate" type="date" required><label>Location</label><input id="location" required><label>Description</label><textarea id="description" rows="3"></textarea><button type="submit">Save event</button><button type="button" id="cancelEdit">Clear form</button></form><?php endif;?>
<table><thead><tr><th>Title</th><th>Category</th><th>Date</th><th>Location</th><th>Details</th><th>Actions</th></tr></thead><tbody id="eventsBody"><tr><td colspan="6">Loading…</td></tr></tbody></table>
<script>
const api='api/events.php', body=document.getElementById('eventsBody'), msg=document.getElementById('message'); let events=[];
function message(text,ok=true){msg.hidden=false;msg.className='flash '+(ok?'success':'error');msg.textContent=text;}
async function request(url,options={}){const r=await fetch(url,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});let data;try{data=await r.json()}catch(parseError){throw new Error('The API returned HTML instead of JSON. Check PHP/database errors and the events table schema.')}if(!r.ok||!data.success)throw new Error(data.message||'Request failed');return data;}
function render(){body.replaceChildren();for(const ev of events){const tr=document.createElement('tr');[ev.title,ev.category,ev.event_date,ev.location,ev.description||''].forEach(v=>{const td=document.createElement('td');td.textContent=v;tr.appendChild(td)});const td=document.createElement('td');<?php if(($_SESSION['role']??'')==='admin'):?>const edit=document.createElement('button');edit.textContent='Edit';edit.onclick=()=>fill(ev);const del=document.createElement('button');del.textContent='Delete';del.className='danger';del.onclick=async()=>{if(confirm('Delete this event?'))try{const d=await request(api,{method:'DELETE',body:JSON.stringify({id:ev.id})});message(d.message);await load()}catch(e){message(e.message,false)}};td.append(edit,del);<?php else:?>td.textContent='—';<?php endif;?>tr.appendChild(td);body.appendChild(tr)}if(!events.length)body.innerHTML='<tr><td colspan="6">No events found.</td></tr>';}
async function load(){try{const d=await request(api);events=d.events;render()}catch(e){message(e.message,false)}}
<?php if(($_SESSION['role']??'')==='admin'):?>
function fill(ev){document.getElementById('eventId').value=ev.id;document.getElementById('title').value=ev.title;document.getElementById('category').value=ev.category;document.getElementById('eventDate').value=ev.event_date;document.getElementById('location').value=ev.location;document.getElementById('description').value=ev.description||'';window.scrollTo({top:0,behavior:'smooth'})}
document.getElementById('cancelEdit').onclick=()=>document.getElementById('eventForm').reset();document.getElementById('eventForm').onsubmit=async e=>{e.preventDefault();const payload={id:document.getElementById('eventId').value,title:document.getElementById('title').value,category:document.getElementById('category').value,event_date:document.getElementById('eventDate').value,location:document.getElementById('location').value,description:document.getElementById('description').value};if(!payload.id)delete payload.id;try{const d=await request(api,{method:'POST',body:JSON.stringify(payload)});message(d.message);e.target.reset();document.getElementById('eventId').value='';await load()}catch(err){message(err.message,false)}};
<?php endif;?>load();
</script><?php page_end(); ?>
